    SELECT COUNT(*) AS cnt FROM loan
),
threshold AS (
    SELECT MAX(amount) AS thresh FROM (
        SELECT amount FROM loan ORDER BY amount LIMIT (SELECT CEIL(0.75 * cnt) FROM params)
    )
)
SELECT loan_id, account_id, date, amount, duration, payments, status
FROM loan, threshold
WHERE loan.amount > threshold.thresh;

